{
  "scripts": {
    "clean": "rm -R dist/* && rm -R dev/* && mkdirp -p dist/media && mkdirp -p dev/media",
    "env": "env",
    "start": "webpack serve --open --host 0.0.0.0 --config webpack.dev.config.js",
    "build-prod": "mkdirp -p dist/media && cp -r src/media/* dist/media && webpack --config webpack.prod.config.js",
    "build-dev": "mkdirp -p dev/media && cp -r src/media/* dev/media && webpack --config webpack.dev.config.js --watch"
  },
  "dependencies": {
    "three": "^0.144.0",
    "webpack-shell-plugin": "^0.5.0",
    "webpack-shell-plugin-next": "^2.2.2"
  },
  "devDependencies": {
    "css-loader": "^6.7.1",
    "html-webpack-plugin": "^5.5.0",
    "mkdirp": "^1.0.4",
    "source-map-loader": "^1.0.0",
    "style-loader": "^3.3.1",
    "webpack": "^5.70.0",
    "webpack-cli": "^4.9.2",
    "webpack-dev-server": "^4.7.4"
  }
}

const path = require("path")
const HtmlWebpackPlugin = require("html-webpack-plugin")
const WebpackShellPluginNext = require("webpack-shell-plugin-next")

module.exports = {
  mode: "production",

  entry: {
    index: "./src/index.js",
    otodojo: "./src/otodojo.js"
  },

  output: {
    filename: "[name].js",
    path: path.resolve(__dirname, "dist"),
  },

  plugins: [
    new HtmlWebpackPlugin({
      template: './src/index.html',
      inject: true,
      chunks: ['index'],
      filename: 'index.html'
    }),
    new HtmlWebpackPlugin({
      template: './src/otodojo.html',
      inject: true,
      chunks: ['otodojo'],
      filename: 'otodojo.html'
    })
  ],

  module: {
    rules: [
      {
        test: /\.css$/i,
        use: ["style-loader", "css-loader"],
      },
    ],
  },

  optimization: {
    runtimeChunk: "single",
    splitChunks: {
      chunks: "all",
      maxInitialRequests: Infinity,
      minSize: 0,
      cacheGroups: {
        vendor: {
          test: /[\\/]node_modules[\\/]/,
          name(module) {
            // get the name. E.g. node_modules/packageName/not/this/part.js
            // or node_modules/packageName
            const packageName = module.context.match(
              /[\\/]node_modules[\\/](.*?)([\\/]|$)/
            )[1]

            // npm package names are URL-safe, but some servers don't like @ symbols
            return `npm.${packageName.replace("@", "")}`
          },
        },
      },
    },
  },
}

const path = require("path")
const HtmlWebpackPlugin = require("html-webpack-plugin")

module.exports = {
  mode: "development",

  entry: {
    index: "./src/index.js",
    otodojo: "./src/otodojo.js"
  },

  output: {
    filename: "[name].js",
    path: path.resolve(__dirname, "dev"),
  },

  devServer: {
    static: "./dev",
  },

  plugins: [
    new HtmlWebpackPlugin({
      template: './src/index.html',
      inject: true,
      chunks: ['index'],
      filename: 'index.html'
    }),
    new HtmlWebpackPlugin({
      template: './src/otodojo.html',
      inject: true,
      chunks: ['otodojo'],
      filename: 'otodojo.html'
    })
  ],

  module: {
    rules: [{
      test: /\.css$/i,
      use: ["style-loader", "css-loader"],
    }, ],
  },
}

