import * as THREE from 'three'
import {OBJLoader} from 'three/examples/jsm/loaders/OBJLoader.js'
import './main.css'

function showCat() {
  var x = document.getElementById("draggableDivCat")
  if (x.style.display === "block") {
    x.style.display = "none"

    x.visibility = "visible"
  } else {
    x.style.display = "block"
    x.visibility = "hidden"
  }
}
window.showCat = showCat

function showAbout() {
  var x = document.getElementById("draggableDivAbout")
  if (x.style.display === "block") {
    x.style.display = "none"

    x.visibility = "visible"
  } else {
    x.style.display = "block"
    x.visibility = "hidden"
  }
}
window.showAbout = showAbout

const elmntNext = document.getElementById("nextButton")
const elmntPrevious = document.getElementById("previousButton")
function catCycleNext() {
  var buttonValue = elmntNext.value

  buttonValue++
  if (buttonValue == 9) {
    buttonValue = 0
  }
  returnCatInfo(buttonValue)
  elmntNext.value = buttonValue
}
window.catCycleNext = catCycleNext

function catCyclePrevious() {
  var buttonValue = elmntNext.value

  buttonValue--
  if (buttonValue == -1) {
    buttonValue = 8
  }
  returnCatInfo(buttonValue)
  elmntNext.value = buttonValue
}
window.catCyclePrevious = catCyclePrevious

// displays the selected div on the catalogue screen
const catIDList = ['catMT001', 'catMT002', 'catMT003', 'catMT004', 'catMTUSB01', 'catMTWL001', 'catMTUSB002', 'catMT005', 'catMINT06']
function returnCatInfo(buttonValue) {
  catIDList.forEach((item) => {
    var itemID = document.getElementById(item)
    itemID.style.display = "none"
  })
  var catID = document.getElementById(catIDList[buttonValue])
  catID.style.display = "inline"
}
window.returnCatInfo = returnCatInfo

// Make the DIV element draggable:
dragElement(document.getElementById("draggableDivCat"))
dragElement(document.getElementById("draggableDivAbout"))

function dragElement(elmnt) {
  var pos1 = 0, pos2 = 0, pos3 = 400, pos4 = 400
  if (document.getElementById(elmnt.id + 'Header')) {
    // if present, the header is where you move the DIV from:
    document.getElementById(elmnt.id + 'Header').onmousedown = dragMouseDown
  } else {
    // otherwise, move the DIV from anywhere inside the DIV:
    elmnt.onmousedown = dragMouseDown
  }

  function dragMouseDown(e) {
    e = e || window.event
    e.preventDefault()
    // get the mouse cursor position at startup:
    pos3 = e.clientX
    pos4 = e.clientY
    document.onmouseup = closeDragElement
    // call a function whenever the cursor moves:
    document.onmousemove = elementDrag
  }

  function elementDrag(e) {
    e = e || window.event
    e.preventDefault()
    // calculate the new cursor position:
    pos1 = pos3 - e.clientX
    pos2 = pos4 - e.clientY
    pos3 = e.clientX
    pos4 = e.clientY
    // set the element's new position:
    elmnt.style.top = (elmnt.offsetTop - pos2) + "px"
    elmnt.style.left = (elmnt.offsetLeft - pos1) + "px"
  }

  function closeDragElement() {
    // stop moving when mouse button is released:
    document.onmouseup = null
    document.onmousemove = null
  }
}
window.dragElement = dragElement

function sleep(ms) {
     return new Promise(resolve => setTimeout(resolve, ms))
}
window.sleep = sleep
////////////////////////////////////////////////////////////////////////////////
function getRandomInt(min, max) {
  min = Math.ceil(min)
  max = Math.floor(max)
  //The maximum is exclusive and the minimum is inclusive
  return Math.floor(Math.random() * (max - min)) + min
}
window.getRandomInt = getRandomInt



  var scene = new THREE.Scene()

  // There's no reason to set the aspect here because we're going
  // to set it every frame anyway so we'll set it to 2 since 2
  // is the the aspect for the canvas default size (300w/150h = 2)
  const camera = new THREE.PerspectiveCamera(70, 2, 1, 1000)

  var renderer = new THREE.WebGLRenderer()

  // White directional light at half intensity shining from the top.
  var directionalLight = new THREE.DirectionalLight( 0xffffff, 1 )
  scene.add( directionalLight )

  // Create a material
  var textureLoader = new THREE.TextureLoader()
  var map = textureLoader.load('media/parts.png')
  var materialColour = new THREE.MeshPhongMaterial({map: map})

  // instantiate a loader
  var loader = new OBJLoader()

  // load a resource
  loader.load(
  	// resource URL
  	'media/space_shuttle_shard.obj',
  	// called when resource is loaded
  	function ( object ) {

  		scene.add( object )
      object.name = "spaceShuttle"
      spaceShuttle = scene.getObjectByName( "spaceShuttle" )

      // For any meshes in the model, add our material.
      object.traverse( function ( node ) {
        if ( node.isMesh ) node.material = materialColour
      } )

  	},
  	// called when loading is in progresses
  	function ( xhr ) {

  		console.log( ( xhr.loaded / xhr.total * 100 ) + '% loaded' )

  	},
  	// called when loading has errors
  	function ( error ) {

  		console.log( 'An error happened' )

  	}
  )

  document.body.appendChild( renderer.domElement )

  var geometry = new THREE.SphereBufferGeometry( 400, 100, 100 )

  var wireframe = new THREE.WireframeGeometry( geometry )

  var line = new THREE.LineSegments( wireframe )
  line.material.depthTest = true
  line.material.opacity = 0.5
  line.material.transparent = true

  var spaceShuttle = 'undefined'

  scene.add( line )

  camera.position.z = 5

  function animate(time) {
    time *= 0.001  // seconds

    resizeCanvasToDisplaySize()

    line.rotation.x = time * 0.05
    line.rotation.y = time * 0.01

    if (spaceShuttle !== 'undefined') {
      spaceShuttle.rotation.x = time * 0.03
      spaceShuttle.rotation.y = time * 0.02
    }

    renderer.render(scene, camera)
    requestAnimationFrame(animate)
  }
  requestAnimationFrame(animate)

  // taken from Stackoverflow: https://stackoverflow.com/questions/29884485/threejs-canvas-size-based-on-container
  function resizeCanvasToDisplaySize() {
    const canvas = renderer.domElement
    // look up the size the canvas is being displayed
    const width = canvas.clientWidth
    const height = canvas.clientHeight

    // adjust displayBuffer size to match
    if (canvas.width !== width || canvas.height !== height) {
      // you must pass false here or three.js sadly fights the browser
      renderer.setSize(width, height, false)
      camera.aspect = width / height
      camera.updateProjectionMatrix()

      // update any render target sizes here
    }
  }

// import './main.css'
import './otodojo.css'
import * as AUDIO from './otodojoAudio.js'

// if user swipes up 

// if window resize we want to change the scope of the image positions
let rect, rectLeftQuarter = 0
const mainScreenElement = document.getElementById('mainScreen')
rect = mainScreenElement.getBoundingClientRect()
rectLeftQuarter = rect.right * 0.25
console.log(rect, rectLeftQuarter)

function updateImageZone() {
    rect = mainScreenElement.getBoundingClientRect()
    rectLeftQuarter = rect.right * 0.25
}
window.addEventListener("resize", updateImageZone)

// track mouse clicks
let mouseX, mouseY = 0
let mouseDown = false
window.addEventListener('pointerdown', logKeyDown)

function logKeyDown(e) {
    mouseDown = true
}
window.addEventListener('pointerup', logKeyUp)

function logKeyUp(e) {
    mouseDown = false
}
window.addEventListener('pointermove', logKey)

function logKey(e) {
    mouseX = e.clientX - 100
    mouseY = e.clientY - 100
    if (mouseX < 0) mouseX = 0
    if (mouseY < 0) mouseY = 0
}

// random int function
function getRndInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min
}
document.getRndInt = getRndInt

function map(value, oldRange, newRange) {
    var newValue = (value - oldRange[0]) * (newRange[1] - newRange[0]) / (oldRange[1] - oldRange[0]) + newRange[0]
    return Math.min(Math.max(newValue, newRange[0]), newRange[1])
}

const shape1 = document.getElementById('shape1')
const shape2 = document.getElementById('shape2')
const shape3 = document.getElementById('shape3')
const shape4 = document.getElementById('shape4')
const shape5 = document.getElementById('shape5')
const shapes = [shape1, shape2, shape3, shape4, shape5]

function shuffleShape(element) {
    element.src = `/media/shapes/shape${getRndInt(1,13)}.png`
}
document.shuffleShape = shuffleShape

shuffleShape(shape1)
shuffleShape(shape2)
shuffleShape(shape3)
shuffleShape(shape4)
shuffleShape(shape5)

const minusOrNotArray = ['', '-']
let zAxisValue = 0

let start, previousTimeStamp
let counter1 = 0
let freqValue0to100 = 0
let freqValue200to400 = 0
let freqValue600to800 = 0
let freqValue1000to1200 = 0
let freqValue2000to5000 = 0
let freqValues = [freqValue0to100, freqValue200to400, freqValue600to800, freqValue1000to1200, freqValue2000to5000]
let highestValue = 25
// main animation function
function step(timestamp) {
    if (start === undefined) {
        start = timestamp
    }

    // make sure some time has passed help reduce processing
    if (timestamp != previousTimeStamp) {
        // work out the average value per chunk of audio data 
        // it's split into a rough freuqncy range
        AUDIO.analyser.getByteFrequencyData(AUDIO.dataArray)

        if (freqValue0to100 > highestValue * 0.8) {
            highestValue = freqValue0to100
        }

        // fft size is 4096 so I think 20,000Hz is across half that range?
        freqValue0to100 = AUDIO.dataArray.slice(0, 10).reduce((partialSum, a) => partialSum + a, 0) * 0.1
        freqValue200to400 = AUDIO.dataArray.slice(100, 200).reduce((partialSum, a) => partialSum + a, 0) * 0.01
        freqValue600to800 = AUDIO.dataArray.slice(600, 700).reduce((partialSum, a) => partialSum + a, 0) * 0.01
        freqValue1000to1200 = AUDIO.dataArray.slice(900, 1000).reduce((partialSum, a) => partialSum + a, 0) * 0.01
        freqValue2000to5000 = AUDIO.dataArray.slice(1200, 1300).reduce((partialSum, a) => partialSum + a, 0) * 0.01
        freqValues = [freqValue0to100, freqValue200to400, freqValue600to800, freqValue1000to1200, freqValue2000to5000]

        shapes[getRndInt(0, shapes.length - 1)].style.filter = `
                                       opacity(${freqValue0to100*0.5}%) 
                                       saturate(${freqValues[getRndInt(0,freqValues.length-1)]*0.5}%)
                                       blur(${Math.abs(highestValue*4-freqValue0to100*4)}px)`
        if (mouseDown === true && AUDIO.playButton.dataset.playing == "true") {
            for (var i = 0; i < shapes.length; i++) {
                shapes[i].style.transform = `rotate(0deg)
                                             scale(1)
                                             translate3d(${mouseX}px,${mouseY}px,0px)`
                shapes[i].style.filter = `blur(0px)
                                          opacity(0.9) 
                                          saturate(${freqValues[i]*0.5}%)
                                          drop-shadow(${freqValue0to100}px ${freqValue200to400}px ${freqValue0to100}px white)`
            }
        }

        if (counter1 > 5 && freqValue0to100 > highestValue * 0.955) {
            if (mouseDown === false) {
                shapes[getRndInt(0, shapes.length - 1)].style.transform = `rotate(${freqValue0to100 % 360}deg)
                                                 scale(${getRndInt(0,20)*0.1})
                                                 translate3d(${minusOrNotArray[getRndInt(0,1)]}${getRndInt(0,rect.right)}px,${minusOrNotArray[getRndInt(0,1)]}${getRndInt(0,rect.right)}px,0px)`
                counter1 = 0
            }

        }
    }
    counter1++
    previousTimeStamp = timestamp
    window.requestAnimationFrame(step)
}

window.requestAnimationFrame(step)

