    line.rotation.x = time * 0.05
    line.rotation.y = time * 0.01

    if (spaceShuttle !== 'undefined') {
      spaceShuttle.rotation.x = time * 0.03
      spaceShuttle.rotation.y = time * 0.02
    }

    renderer.render(scene, camera)
    requestAnimationFrame(animate)
  }
  requestAnimationFrame(animate)

